--
-- Name: assign_ticket(integer, integer, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_ticket(p_ticket_id integer, p_assigned_to integer, p_assigned_email text, p_assigned_phone text, p_date_assigned date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

DECLARE t RECORD;
BEGIN
  SELECT region_id, province_id, district_id, facility_id, created_by
  INTO t
  FROM tickets
  WHERE ticket_id = p_ticket_id
  FOR UPDATE;

  IF NOT has_permission(current_setting('app.user_id')::INT,'tickets','assign',
                        t.region_id,t.province_id,t.district_id,t.facility_id,t.created_by) THEN
    RAISE EXCEPTION 'Not authorised to assign this ticket';
  END IF;

  UPDATE tickets
  SET assigned_to       = p_assigned_to,
      assigned_to_email = p_assigned_email,
      assigned_to_phone = p_assigned_phone,
      date_assigned     = p_date_assigned,
      status            = 'Assigned',
      updated_at        = NOW()
  WHERE ticket_id = p_ticket_id;
END 
$$;


--
-- Name: audit_trigger_fn(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_trigger_fn() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id INT;
  v_record_id INT;
  v_col_exists BOOLEAN;
BEGIN
  -- 1️⃣ Try to read current app user
  BEGIN
    v_user_id := NULLIF(current_setting('app.user_id', true), '')::INT;
  EXCEPTION WHEN OTHERS THEN
    v_user_id := NULL;
  END;

  -- 2️⃣ Fallback to system user if none
  IF v_user_id IS NULL THEN
    SELECT user_id INTO v_user_id FROM users WHERE email = 'system@localhost' LIMIT 1;

    IF v_user_id IS NULL THEN
      BEGIN
        VALUES ('system', 'system@localhost', 'SYSTEM_USER')
        ON CONFLICT (email) DO NOTHING;
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;

      SELECT user_id INTO v_user_id FROM users WHERE email = 'system@localhost' LIMIT 1;
    END IF;
  END IF;

  -- 3️⃣ Dynamically determine record_id column (ticket_id, user_id, etc.)
  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
     WHERE table_name = TG_TABLE_NAME AND column_name = 'ticket_id'
  ) INTO v_col_exists;

  IF v_col_exists THEN
    v_record_id := COALESCE((NEW).ticket_id, (OLD).ticket_id);
  ELSE
    BEGIN
      v_record_id := COALESCE(
        (NEW).id,
        (OLD).id,
        (NEW).user_id,
        (OLD).user_id,
        (NEW).role_id,
        (OLD).role_id
      );
    EXCEPTION WHEN OTHERS THEN
      v_record_id := NULL;
    END;
  END IF;

  -- 4️⃣ Insert the audit log entry
    user_id, action, table_name, record_id, old_value, new_value, "timestamp"
  ) VALUES (
    v_user_id,
    TG_OP,
    TG_TABLE_NAME,
    v_record_id,
    row_to_json(OLD)::text,
    row_to_json(NEW)::text,
    NOW()
  );

  -- 5️⃣ Return record as appropriate
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$$;


--
-- Name: calculate_sla_due_date(character varying, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_sla_due_date(ticket_priority character varying, created_date timestamp without time zone) RETURNS timestamp without time zone
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF ticket_priority = 'Critical' THEN
        RETURN created_date + INTERVAL '3 days';
    ELSIF ticket_priority = 'High' THEN
        RETURN created_date + INTERVAL '5 days';
    ELSIF ticket_priority = 'Medium' THEN
        RETURN created_date + INTERVAL '7 days';
    ELSE
        RETURN created_date + INTERVAL '14 days';
    END IF;
END;
$$;


--
-- Name: calculate_sla_due_date(public.priority_enum, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_sla_due_date(p_priority public.priority_enum, p_created_at timestamp without time zone) RETURNS timestamp without time zone
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN p_created_at +
    CASE p_priority
      WHEN 'Critical' THEN INTERVAL '24 hours'
      WHEN 'High'     THEN INTERVAL '48 hours'
      WHEN 'Medium'   THEN INTERVAL '72 hours'
      WHEN 'Low'      THEN INTERVAL '168 hours'   -- 7 days
      ELSE INTERVAL '72 hours'                    -- fallback
    END;
END;
$$;


--
-- Name: check_sla_and_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_sla_and_queue() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
    rec RECORD;
    sla_limit INT;
BEGIN
    FOR rec IN
        SELECT t.ticket_id, t.priority, t.created_at, u.user_id AS recipient_user_id
        FROM tickets t
        JOIN users u ON u.user_id = t.created_by
        WHERE t.status NOT IN ('Closed', 'Resolved')
    LOOP
        SELECT sla_days INTO sla_limit FROM sla_settings WHERE priority = rec.priority::text;
        IF sla_limit IS NOT NULL AND (CURRENT_DATE - DATE(rec.created_at)) >= sla_limit THEN
            VALUES (rec.ticket_id, rec.recipient_user_id,
                    'SLA Breach: Ticket ' || rec.ticket_id || ' has exceeded SLA limit of ' || sla_limit || ' days.',
                    'email');
        END IF;
    END LOOP;
END;

$$;


--
-- Name: compute_ticket_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_ticket_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    reg_abbrev TEXT;
    prov_abbrev TEXT;
    dist_abbrev TEXT;
    fac_abbrev TEXT;
    ts_local TEXT;
    serial_sfx TEXT;
BEGIN
    -- 🔹 Automatically fill location IDs from facility
    SELECT 
        f.region_id, 
        f.province_id, 
        f.district_id
    INTO 
        NEW.region_id, 
        NEW.province_id, 
        NEW.district_id
    FROM facilities f
    WHERE f.facility_id = NEW.facility_id;

    -- 🔹 Build location abbreviations
    SELECT UPPER(LEFT(r.region_name, 3)) INTO reg_abbrev FROM regions r WHERE r.region_id = NEW.region_id;
    SELECT UPPER(LEFT(p.province_name, 3)) INTO prov_abbrev FROM provinces p WHERE p.province_id = NEW.province_id;
    SELECT UPPER(LEFT(d.district_name, 3)) INTO dist_abbrev FROM districts d WHERE d.district_id = NEW.district_id;
    SELECT UPPER(LEFT(f.facility_name, 3)) INTO fac_abbrev FROM facilities f WHERE f.facility_id = NEW.facility_id;

    -- 🔹 Generate local timestamp and serial suffix
    ts_local := TO_CHAR((NOW() AT TIME ZONE 'Pacific/Port_Moresby'), 'YYYYMMDD-HH24MISS');
    serial_sfx := LPAD(NEW.ticket_id::TEXT, 4, '0');

    -- 🔹 Construct final ticket reference
    NEW.ticket_reference_number :=
        reg_abbrev || '-' ||
        prov_abbrev || '-' ||
        dist_abbrev || '-' ||
        fac_abbrev || '-' ||
        ts_local || '-' ||
        serial_sfx;

    RETURN NEW;
END;
$$;


--
-- Name: create_user_with_credentials(text, text, text, text, integer, integer, integer, integer, integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_user_with_credentials(p_username text, p_email text, p_phone_number text, p_password text, p_role_id integer, p_assigned_region_id integer DEFAULT NULL::integer, p_assigned_province_id integer DEFAULT NULL::integer, p_assigned_district_id integer DEFAULT NULL::integer, p_assigned_facility_id integer DEFAULT NULL::integer, p_is_national_access boolean DEFAULT false, p_actor_user_id integer DEFAULT 90) RETURNS TABLE(user_id integer, role_id integer)
    LANGUAGE plpgsql
    AS $$

DECLARE
    new_user_id INTEGER;
BEGIN
    -- Step 1: Insert user
        username,
        email,
        phone_number,
        password,
        password_hash,
        assigned_region_id,
        assigned_province_id,
        assigned_district_id,
        assigned_facility_id,
        is_national_access,
        must_change_password
    )
    VALUES (
        p_username,
        p_email,
        p_phone_number,
        'Set via stored function',  -- Optional marker
        crypt(p_password, gen_salt('bf')),
        p_assigned_region_id,
        p_assigned_province_id,
        p_assigned_district_id,
        p_assigned_facility_id,
        p_is_national_access,
        TRUE
    )
    RETURNING user_id INTO new_user_id;

    -- Step 2: Assign role
    VALUES (new_user_id, p_role_id);

    -- Step 3: Log in audit
        user_id,
        action,
        table_name,
        record_id,
        new_value
    )
    VALUES (
        COALESCE(p_actor_user_id, 90),
        'CREATE_USER',
        'users',
        new_user_id,
        json_build_object(
            'username', p_username,
            'email', p_email,
            'role_id', p_role_id
        )::text
    );

    RETURN QUERY
    SELECT new_user_id, p_role_id;
END;

$$;


--
-- Name: create_user_with_role(text, text, text, integer, integer, integer, integer, integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_user_with_role(p_username text, p_email text, p_phone_number text, p_role_id integer, p_assigned_region_id integer DEFAULT NULL::integer, p_assigned_province_id integer DEFAULT NULL::integer, p_assigned_district_id integer DEFAULT NULL::integer, p_assigned_facility_id integer DEFAULT NULL::integer, p_is_national_access boolean DEFAULT false, p_actor_user_id integer DEFAULT 90) RETURNS TABLE(user_id integer, role_id integer)
    LANGUAGE plpgsql
    AS $$

DECLARE
    new_user_id INTEGER;
BEGIN
    -- Step 1: Insert user
        username,
        email,
        phone_number,
        assigned_region_id,
        assigned_province_id,
        assigned_district_id,
        assigned_facility_id,
        is_national_access,
        must_change_password
    )
    VALUES (
        p_username,
        p_email,
        p_phone_number,
        p_assigned_region_id,
        p_assigned_province_id,
        p_assigned_district_id,
        p_assigned_facility_id,
        p_is_national_access,
        TRUE
    )
    RETURNING user_id INTO new_user_id;

    -- Step 2: Assign role
    VALUES (new_user_id, p_role_id);

    -- Step 3: Log the creation in audit trail
        user_id,
        action,
        table_name,
        record_id,
        new_value
    )
    VALUES (
        COALESCE(p_actor_user_id, 90),
        'CREATE_USER',
        'users',
        new_user_id,
        json_build_object(
            'username', p_username,
            'email', p_email,
            'role_id', p_role_id
        )::text
    );

    -- Step 4: Return created IDs
    RETURN QUERY
    SELECT new_user_id, p_role_id;
END;

$$;


--
-- Name: escalate_ticket(integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalate_ticket(p_ticket_id integer, p_to_user_id integer, p_to_level text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

DECLARE t RECORD;
BEGIN
  SELECT region_id, province_id, district_id, facility_id, created_by
  INTO t
  FROM tickets
  WHERE ticket_id = p_ticket_id
  FOR UPDATE;

  IF NOT has_permission(current_setting('app.user_id')::INT,'tickets','escalate',
                        t.region_id,t.province_id,t.district_id,t.facility_id,t.created_by) THEN
    RAISE EXCEPTION 'Not authorised to escalate this ticket';
  END IF;

    ticket_id, from_user_id, to_user_id, from_level, to_level, reason, escalation_date, status
  ) VALUES (
    p_ticket_id,
    current_setting('app.user_id')::INT,
    p_to_user_id,
    NULL,             -- set from_level if you track it (e.g., via userâ€™s role)
    p_to_level,
    p_reason,
    NOW(),
    'pending'
  );

  UPDATE tickets
  SET status = 'Escalated', updated_at = NOW()
  WHERE ticket_id = p_ticket_id;
END 
$$;


--
-- Name: fn_audit_tickets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_tickets() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_action TEXT;
    v_old_value TEXT;
    v_new_value TEXT;
    v_user_id INTEGER;
BEGIN
    -- Identify user_id from session (if available)
    BEGIN
        v_user_id := current_setting('app.user_id', true)::INT;
    EXCEPTION WHEN OTHERS THEN
        v_user_id := NULL;
    END;

    -- Determine action type
    IF TG_OP = 'INSERT' THEN
        v_action := 'CREATE';
        v_new_value := row_to_json(NEW)::TEXT;
    ELSIF TG_OP = 'UPDATE' THEN
        v_action := 'UPDATE';
        v_old_value := row_to_json(OLD)::TEXT;
        v_new_value := row_to_json(NEW)::TEXT;
    ELSIF TG_OP = 'DELETE' THEN
        v_action := 'DELETE';
        v_old_value := row_to_json(OLD)::TEXT;
    END IF;

    -- ✅ Skip audit insert if user_id is missing or invalid
    IF v_user_id IS NOT NULL AND EXISTS (SELECT 1 FROM users WHERE user_id = v_user_id) THEN
        VALUES (v_user_id, v_action, TG_TABLE_NAME, COALESCE(NEW.ticket_id, OLD.ticket_id), v_old_value, v_new_value);
    ELSE
        RAISE NOTICE 'Skipping audit insert — invalid or external user_id: %', v_user_id;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: generate_ticket_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_ticket_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    reg_code TEXT;
    prov_code TEXT;
    dist_code TEXT;
    fac_code TEXT;
    seq_num INT;
    ref_num TEXT;
BEGIN
    -- Get location codes
    SELECT 
        UPPER(COALESCE(SUBSTRING(r.region_name FROM 1 FOR 3), 'UNK')),
        UPPER(COALESCE(SUBSTRING(p.province_name FROM 1 FOR 3), 'UNK')),
        UPPER(COALESCE(SUBSTRING(d.district_name FROM 1 FOR 3), 'UNK')),
        UPPER(COALESCE(f.facility_code, SUBSTRING(f.facility_name FROM 1 FOR 3), 'UNK'))
    INTO reg_code, prov_code, dist_code, fac_code
    FROM facilities f
    LEFT JOIN districts d ON f.district_id = d.district_id
    LEFT JOIN provinces p ON d.province_id = p.province_id
    LEFT JOIN regions r ON p.region_id = r.region_id
    WHERE f.facility_id = NEW.facility_id;

    -- Get next serial number
    SELECT COUNT(*) + 1 INTO seq_num 
    FROM tickets 
    WHERE facility_id = NEW.facility_id 
    AND TO_CHAR(created_at, 'YYYY-MM') = TO_CHAR(NEW.created_at, 'YYYY-MM');

    -- Format
    ref_num := reg_code || '-' || prov_code || '-' || dist_code || '-' || fac_code || '-' || LPAD(seq_num::TEXT, 3, '0') || '-' || TO_CHAR(NEW.created_at, 'YYYY-MM');
    
    NEW.ticket_reference_number := ref_num;
    
    RETURN NEW;
END;
$$;


--
-- Name: get_available_technicians(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_available_technicians(facility_id integer) RETURNS TABLE(user_id integer, username character varying, full_name character varying, phone_number character varying, user_level character varying)
    LANGUAGE plpgsql
    AS $$

DECLARE
    target_facility RECORD;
BEGIN
    -- Get facility details
    SELECT f.*, r.region_name, p.province_name, d.district_name 
    INTO target_facility
    FROM facilities f
    LEFT JOIN regions r ON f.region_id = r.region_id
    LEFT JOIN provinces p ON f.province_id = p.province_id
    LEFT JOIN districts d ON f.district_id = d.district_id
    WHERE f.facility_id = get_available_technicians.facility_id;
    
    RETURN QUERY
    SELECT 
        u.user_id,
        u.username::VARCHAR(255),
        (u.first_name || ' ' || u.last_name)::VARCHAR(510) as full_name,
        u.phone_number::VARCHAR(50),
        CASE 
            WHEN u.assigned_facility_id IS NOT NULL THEN 'facility'::VARCHAR(20)
            WHEN u.assigned_district_id IS NOT NULL THEN 'district'::VARCHAR(20)
            WHEN u.assigned_province_id IS NOT NULL THEN 'province'::VARCHAR(20)
            WHEN u.assigned_region_id IS NOT NULL THEN 'region'::VARCHAR(20)
            ELSE 'national'::VARCHAR(20)
        END as user_level
    FROM users u
    INNER JOIN user_roles ur ON u.user_id = ur.user_id
    INNER JOIN roles r ON ur.role_id = r.role_id
    WHERE r.role_name IN ('Technician', 'Manager')
    AND u.is_active = true
    AND (
        -- National users can access all facilities
        u.is_national_access = true
        -- Users assigned to the same region
        OR u.assigned_region_id = target_facility.region_id
        -- Users assigned to the same province
        OR u.assigned_province_id = target_facility.province_id
        -- Users assigned to the same district
        OR u.assigned_district_id = target_facility.district_id
        -- Users assigned to the specific facility
        OR u.assigned_facility_id = target_facility.facility_id
        -- Users with explicit access to arrays
        OR (u.accessible_regions IS NOT NULL AND target_facility.region_id = ANY(u.accessible_regions))
        OR (u.accessible_provinces IS NOT NULL AND target_facility.province_id = ANY(u.accessible_provinces))
        OR (u.accessible_districts IS NOT NULL AND target_facility.district_id = ANY(u.accessible_districts))
        OR (u.accessible_facilities IS NOT NULL AND target_facility.facility_id = ANY(u.accessible_facilities))
    )
    ORDER BY 
        -- Prioritize facility-level technicians first
        CASE 
            WHEN u.assigned_facility_id = target_facility.facility_id THEN 1
            WHEN u.assigned_district_id = target_facility.district_id THEN 2
            WHEN u.assigned_province_id = target_facility.province_id THEN 3
            WHEN u.assigned_region_id = target_facility.region_id THEN 4
            ELSE 5
        END;
END;

$$;


--
-- Name: get_available_technicians_simple(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_available_technicians_simple(facility_id integer) RETURNS TABLE(user_id integer, username text, full_name text, phone_number text, user_level text)
    LANGUAGE plpgsql
    AS $$

BEGIN
    RETURN QUERY
    SELECT 
        u.user_id,
        u.username,
        COALESCE(u.first_name || ' ' || u.last_name, u.username) as full_name,
        COALESCE(u.phone_number, 'No phone') as phone_number,
        CASE 
            WHEN u.assigned_facility_id IS NOT NULL THEN 'facility'
            WHEN u.assigned_district_id IS NOT NULL THEN 'district' 
            WHEN u.assigned_province_id IS NOT NULL THEN 'province'
            WHEN u.assigned_region_id IS NOT NULL THEN 'region'
            ELSE 'national'
        END as user_level
    FROM users u
    INNER JOIN user_roles ur ON u.user_id = ur.user_id
    INNER JOIN roles r ON ur.role_id = r.role_id
    WHERE r.role_name IN ('Technician', 'Manager')
    AND u.is_active = true
    AND u.is_national_access = true  -- For testing, just get national users
    ORDER BY u.user_id
    LIMIT 10;  -- Limit for testing
END;

$$;


--
-- Name: get_user_accessible_facilities(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_accessible_facilities(user_id integer) RETURNS TABLE(facility_id integer, facility_name character varying, district_name character varying, province_name character varying, region_name character varying)
    LANGUAGE plpgsql
    AS $$

BEGIN
    RETURN QUERY
    SELECT 
        f.facility_id,
        f.facility_name,
        d.district_name,
        p.province_name,
        r.region_name
    FROM facilities f
    LEFT JOIN districts d ON f.district_id = d.district_id
    LEFT JOIN provinces p ON f.province_id = p.province_id
    LEFT JOIN regions r ON f.region_id = r.region_id
    JOIN users u ON u.user_id = get_user_accessible_facilities.user_id
    WHERE (
        u.is_national_access = true
        OR f.region_id = u.assigned_region_id
        OR f.province_id = u.assigned_province_id
        OR f.district_id = u.assigned_district_id
        OR f.facility_id = u.assigned_facility_id
        OR (u.accessible_regions IS NOT NULL AND f.region_id = ANY(u.accessible_regions))
        OR (u.accessible_provinces IS NOT NULL AND f.province_id = ANY(u.accessible_provinces))
        OR (u.accessible_districts IS NOT NULL AND f.district_id = ANY(u.accessible_districts))
        OR (u.accessible_facilities IS NOT NULL AND f.facility_id = ANY(u.accessible_facilities))
    )
    AND f.is_functioning = true;
END;

$$;


--
-- Name: has_permission(integer, text, text, integer, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(p_user_id integer, p_resource text, p_action text, p_region_id integer, p_province_id integer, p_district_id integer, p_facility_id integer, p_created_by_email text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

DECLARE
  scopes  TEXT[];
BEGIN
  SELECT ARRAY_AGG(DISTINCT p.scope)
  INTO scopes
  FROM role_permissions rp
  JOIN permissions p ON p.permission_id = rp.permission_id
  JOIN v_user_roles ur ON ur.role_id = rp.role_id
  WHERE ur.user_id = p_user_id
    AND p.resource = p_resource
    AND p.action   = p_action;

  IF scopes IS NULL THEN
    RETURN FALSE;
  END IF;

  IF 'national' = ANY(scopes) THEN RETURN TRUE; END IF;

  IF 'region' = ANY(scopes) AND EXISTS (
      SELECT 1 FROM v_user_scope s WHERE s.user_id=p_user_id AND s.region_id=p_region_id
  ) THEN RETURN TRUE; END IF;

  IF 'province' = ANY(scopes) AND EXISTS (
      SELECT 1 FROM v_user_scope s WHERE s.user_id=p_user_id AND s.province_id=p_province_id
  ) THEN RETURN TRUE; END IF;

  IF 'district' = ANY(scopes) AND EXISTS (
      SELECT 1 FROM v_user_scope s WHERE s.user_id=p_user_id AND s.district_id=p_district_id
  ) THEN RETURN TRUE; END IF;

  IF 'facility' = ANY(scopes) AND EXISTS (
      SELECT 1 FROM v_user_scope s WHERE s.user_id=p_user_id AND s.facility_id=p_facility_id
  ) THEN RETURN TRUE; END IF;

  IF 'own' = ANY(scopes) AND p_created_by_email IS NOT NULL
                         AND p_created_by_email = current_setting('app.user_email', true)
  THEN RETURN TRUE; END IF;

  RETURN FALSE;
END

$$;


--
-- Name: has_repair_permission(integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_repair_permission(p_user_id integer, p_action text, p_repair_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

DECLARE
  r RECORD;
  t RECORD;
BEGIN
  SELECT * INTO r FROM repairs WHERE repair_id = p_repair_id;
  IF NOT FOUND THEN RETURN FALSE; END IF;

  -- if linked to a ticket, inherit ticket geography
  SELECT region_id, province_id, district_id, facility_id, created_by
  INTO t
  FROM tickets
  WHERE ticket_id = r.ticket_id;

  IF FOUND THEN
    RETURN has_permission(
      p_user_id, 'repairs', p_action,
      t.region_id, t.province_id, t.district_id, t.facility_id, t.created_by
    );
  ELSE
    RETURN has_permission(
      p_user_id, 'repairs', p_action,
      NULL, NULL, NULL, r.facility_id, r.created_by
    );
  END IF;
END 
$$;


--
-- Name: has_ticket_permission(integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_ticket_permission(p_user_id integer, p_action text, p_ticket_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$

DECLARE t RECORD;
BEGIN
  SELECT region_id, province_id, district_id, facility_id, created_by
  INTO t
  FROM tickets
  WHERE ticket_id = p_ticket_id;

  IF NOT FOUND THEN
    RETURN FALSE;
  END IF;

  RETURN has_permission(
    p_user_id, 'tickets', p_action,
    t.region_id, t.province_id, t.district_id, t.facility_id, t.created_by
  );
END

$$;


--
-- Name: hash_user_password(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hash_user_password() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$

BEGIN
  IF NEW.password_hash IS NULL OR NEW.password_hash = '' THEN
    NEW.password_hash := crypt('changeme', gen_salt('bf'));
  ELSIF position('$2a$' IN NEW.password_hash) = 0 THEN
    -- not yet hashed, so hash it
    NEW.password_hash := crypt(NEW.password_hash, gen_salt('bf'));
  END IF;
  RETURN NEW;
END;

$_$;


--
-- Name: link_user_to_group(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_user_to_group() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN
  SELECT NEW.user_id, g.group_id
  FROM user_groups g
  WHERE g.role_id = NEW.role_id
  ON CONFLICT (user_id, group_id) DO NOTHING;
  RETURN NEW;
END;

$$;


--
-- Name: log_ticket_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_ticket_activity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_action TEXT;
    v_details TEXT;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_action := 'CREATE';
        v_details := 'New ticket created by ' || COALESCE(NEW.reported_by_name, 'System');

    ELSIF TG_OP = 'UPDATE' THEN
        v_action := 'UPDATE';
        v_details := 'Ticket updated by ' || COALESCE(NEW.reported_by_name, 'System');

    ELSIF TG_OP = 'DELETE' THEN
        v_action := 'DELETE';
        v_details := 'Ticket deleted';
    END IF;

    VALUES (
        COALESCE(NEW.ticket_id, OLD.ticket_id),
        NEW.assigned_to,
        v_action,
        v_details,
        NOW()
    );

    RETURN NEW;
END;
$$;


--
-- Name: parse_gps_coordinates(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_gps_coordinates(gps_text text) RETURNS TABLE(latitude numeric, longitude numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    parts TEXT[];
    lat NUMERIC;
    lng NUMERIC;
    clean_text TEXT;
    lat_part TEXT;
    lng_part TEXT;
BEGIN
    IF gps_text IS NULL OR gps_text = '' THEN
        RETURN QUERY SELECT NULL::NUMERIC, NULL::NUMERIC;
        RETURN;
    END IF;
    
    -- Clean the text
    clean_text = TRIM(gps_text);
    
    -- Debug: Print what we're processing
    -- RAISE NOTICE 'Processing: %', clean_text;
    
    -- Method 1: Try simple comma-separated decimal format (most common)
    IF clean_text LIKE '%,%' THEN
        parts = regexp_split_to_array(clean_text, '\s*,\s*');
        
        IF array_length(parts, 1) >= 2 THEN
            BEGIN
                lat = parts[1]::NUMERIC;
                lng = parts[2]::NUMERIC;
                
                -- Validate ranges
                IF lat >= -90 AND lat <= 90 AND lng >= -180 AND lng <= 180 THEN
                    RETURN QUERY SELECT lat, lng;
                    RETURN;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                -- Continue to other methods
                -- RAISE NOTICE 'Method 1 failed for: %', clean_text;
            END;
        END IF;
    END IF;
    
    -- Method 2: Try space or tab separated
    IF clean_text ~ '[-0-9\.]+\s+[-0-9\.]+' THEN
        BEGIN
            parts = regexp_split_to_array(clean_text, '\s+');
            IF array_length(parts, 1) >= 2 THEN
                lat = parts[1]::NUMERIC;
                lng = parts[2]::NUMERIC;
                
                IF lat >= -90 AND lat <= 90 AND lng >= -180 AND lng <= 180 THEN
                    RETURN QUERY SELECT lat, lng;
                    RETURN;
                END IF;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            -- RAISE NOTICE 'Method 2 failed for: %', clean_text;
        END;
    END IF;
    
    -- Method 3: Try semicolon separated
    IF clean_text LIKE '%;%' THEN
        BEGIN
            parts = regexp_split_to_array(clean_text, '\s*;\s*');
            IF array_length(parts, 1) >= 2 THEN
                lat = parts[1]::NUMERIC;
                lng = parts[2]::NUMERIC;
                
                IF lat >= -90 AND lat <= 90 AND lng >= -180 AND lng <= 180 THEN
                    RETURN QUERY SELECT lat, lng;
                    RETURN;
                END IF;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            -- RAISE NOTICE 'Method 3 failed for: %', clean_text;
        END;
    END IF;
    
    -- Method 4: Try to parse DMS format (simplified approach)
    -- Look for pattern like: S 9 27 52.9 E 147 11 44.4
    IF clean_text ~* '[ns]\s+[0-9]+\s+[0-9]+\s+[0-9\.]+\s+[ew]\s+[0-9]+\s+[0-9]+\s+[0-9\.]+' THEN
        BEGIN
            -- Extract components using regex
            lat_part = substring(clean_text from '[ns]\s+([0-9]+\s+[0-9]+\s+[0-9\.]+)');
            lng_part = substring(clean_text from '[ew]\s+([0-9]+\s+[0-9]+\s+[0-9\.]+)');
            
            IF lat_part IS NOT NULL AND lng_part IS NOT NULL THEN
                DECLARE
                    lat_parts TEXT[];
                    lng_parts TEXT[];
                    lat_deg NUMERIC;
                    lat_min NUMERIC;
                    lat_sec NUMERIC;
                    lng_deg NUMERIC;
                    lng_min NUMERIC;
                    lng_sec NUMERIC;
                BEGIN
                    lat_parts = regexp_split_to_array(lat_part, '\s+');
                    lng_parts = regexp_split_to_array(lng_part, '\s+');
                    
                    IF array_length(lat_parts, 1) >= 3 AND array_length(lng_parts, 1) >= 3 THEN
                        lat_deg = lat_parts[1]::NUMERIC;
                        lat_min = lat_parts[2]::NUMERIC;
                        lat_sec = lat_parts[3]::NUMERIC;
                        
                        lng_deg = lng_parts[1]::NUMERIC;
                        lng_min = lng_parts[2]::NUMERIC;
                        lng_sec = lng_parts[3]::NUMERIC;
                        
                        -- Convert DMS to decimal
                        lat = lat_deg + (lat_min / 60) + (lat_sec / 3600);
                        lng = lng_deg + (lng_min / 60) + (lng_sec / 3600);
                        
                        -- Apply direction
                        IF lower(substring(clean_text from '[ns]')) = 's' THEN
                            lat = -lat;
                        END IF;
                        IF lower(substring(clean_text from '[ew]')) = 'w' THEN
                            lng = -lng;
                        END IF;
                        
                        IF lat >= -90 AND lat <= 90 AND lng >= -180 AND lng <= 180 THEN
                            RETURN QUERY SELECT lat, lng;
                            RETURN;
                        END IF;
                    END IF;
                END;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            -- RAISE NOTICE 'Method 4 failed for: %', clean_text;
        END;
    END IF;
    
    -- If nothing worked, return NULL
    RETURN QUERY SELECT NULL::NUMERIC, NULL::NUMERIC;
    
END;
$$;


--
-- Name: parse_latlng_string(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_latlng_string(gps_text text) RETURNS TABLE(lat numeric, lng numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF gps_text IS NULL OR gps_text = '' THEN
        RETURN QUERY SELECT NULL::NUMERIC, NULL::NUMERIC;
        RETURN;
    END IF;
    
    gps_text = TRIM(gps_text);
    
    -- Handle LatLng(latitude, longitude) format
    IF position('LatLng(' in gps_text) = 1 THEN
        DECLARE
            content TEXT;
            comma_pos INTEGER;
        BEGIN
            -- Extract content inside parentheses: LatLng(-9.47692008957118,147.1787784389744)
            content = substring(gps_text from 'LatLng\(([^)]+)\)');
            
            -- Find comma position
            comma_pos = position(',' in content);
            
            IF comma_pos > 0 THEN
                lat = TRIM(substring(content from 1 for comma_pos - 1))::NUMERIC;
                lng = TRIM(substring(content from comma_pos + 1))::NUMERIC;
                
                -- Validate ranges
                IF lat BETWEEN -90 AND 90 AND lng BETWEEN -180 AND 180 THEN
                    RETURN QUERY SELECT lat, lng;
                    RETURN;
                END IF;
            END IF;
        END;
    
    -- Handle simple comma-separated format
    ELSIF position(',' in gps_text) > 0 THEN
        BEGIN
            lat = split_part(gps_text, ',', 1)::NUMERIC;
            lng = split_part(gps_text, ',', 2)::NUMERIC;
            
            IF lat BETWEEN -90 AND 90 AND lng BETWEEN -180 AND 180 THEN
                RETURN QUERY SELECT lat, lng;
                RETURN;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            -- Do nothing
        END;
    END IF;
    
    -- Return null if parsing failed
    RETURN QUERY SELECT NULL::NUMERIC, NULL::NUMERIC;
END;
$$;


--
-- Name: update_geom_from_latlong(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_geom_from_latlong() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    -- Parse GPS coordinates from LatLng format if needed
    IF NEW.gps_coordinates IS NOT NULL AND NEW.gps_coordinates != '' 
       AND (NEW.latitude IS NULL OR NEW.longitude IS NULL) THEN
        
        -- Handle LatLng(lat, lng) format
        IF NEW.gps_coordinates ~* '^LatLng\([^)]+\)$' THEN
            DECLARE
                content TEXT;
                parts TEXT[];
            BEGIN
                content = SUBSTRING(NEW.gps_coordinates FROM 'LatLng\(([^)]+)\)');
                parts = string_to_array(content, ',');
                
                IF array_length(parts, 1) >= 2 THEN
                    NEW.latitude = TRIM(parts[1])::NUMERIC;
                    NEW.longitude = TRIM(parts[2])::NUMERIC;
                END IF;
            END;
        END IF;
    END IF;
    
    -- Update geom from latitude/longitude
    IF NEW.latitude IS NOT NULL AND NEW.longitude IS NOT NULL THEN
        NEW.geom = ST_SetSRID(ST_MakePoint(NEW.longitude, NEW.latitude), 4326);
    END IF;
    
    -- Always update timestamp
    NEW.updated_at = CURRENT_TIMESTAMP;
    
    RETURN NEW;
END;
$_$;


--
-- Name: update_repair_status(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_repair_status(p_repair_id integer, p_new_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

BEGIN
  IF NOT has_repair_permission(current_setting('app.user_id')::INT,'update',p_repair_id)
     AND NOT has_repair_permission(current_setting('app.user_id')::INT,'close',p_repair_id)
  THEN
    RAISE EXCEPTION 'Not authorised to update this repair';
  END IF;

  UPDATE repairs
  SET status = p_new_status,
      updated_at = NOW()
  WHERE repair_id = p_repair_id;
END 
$$;


--
-- Name: update_ticket_timing_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_ticket_timing_metrics() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- SLA due date
    NEW.sla_due_date =
        calculate_sla_due_date(NEW.priority::priority_enum, NEW.created_at);

    -- Total days open
    NEW.total_days_open =
        EXTRACT(EPOCH FROM (NOW() - NEW.created_at)) / 86400;

    -- Overdue flag
    IF NOW() > NEW.sla_due_date THEN
        NEW.is_overdue = TRUE;
    ELSE
        NEW.is_overdue = FALSE;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


--
-- Name: verify_user_login(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_user_login(p_login text, p_password text) RETURNS TABLE(user_id integer, username character varying, email character varying, first_name character varying, last_name character varying, is_active boolean, is_national_access boolean, role_id integer, role_name character varying, assigned_region_id integer, assigned_province_id integer, assigned_district_id integer, assigned_facility_id integer, accessible_regions integer[], accessible_provinces integer[], accessible_districts integer[], accessible_facilities integer[], permissions character varying[], must_change_password boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user RECORD;
  v_ip TEXT;
BEGIN
  -- Optional: capture IP if your Appsmith proxy passes it via custom header (else leave NULL)
  v_ip := NULL;

  SELECT * INTO v_user
  FROM users u
  WHERE LOWER(u.username) = LOWER(p_login)
     OR LOWER(u.email) = LOWER(p_login)
  LIMIT 1;

  IF v_user IS NULL THEN
    -- user not found
    VALUES (p_login, v_ip, FALSE, 'User not found');
    RETURN;
  END IF;

  IF NOT v_user.is_active THEN
    -- inactive account
    VALUES (p_login, v_ip, v_user.user_id, v_user.username, v_user.email, FALSE, 'User inactive');
    RETURN;
  END IF;

  IF v_user.password_hash = crypt(p_password, v_user.password_hash) THEN
    -- ✅ successful login
    VALUES (p_login, v_ip, v_user.user_id, v_user.username, v_user.email, TRUE);

    RETURN QUERY
    SELECT 
      u.user_id,
      u.username,
      u.email,
      u.first_name,
      u.last_name,
      u.is_active,
      u.is_national_access,
      u.role_id,
      r.role_name,
      u.assigned_region_id,
      u.assigned_province_id,
      u.assigned_district_id,
      u.assigned_facility_id,
      u.accessible_regions,
      u.accessible_provinces,
      u.accessible_districts,
      u.accessible_facilities,
      ARRAY_AGG(p.permission_name) AS permissions,
      u.must_change_password
    FROM users u
    JOIN roles r ON u.role_id = r.role_id
    LEFT JOIN role_permissions rp ON r.role_id = rp.role_id
    LEFT JOIN permissions p ON rp.permission_id = p.permission_id
    WHERE u.user_id = v_user.user_id
    GROUP BY u.user_id, r.role_name;
  ELSE
    -- ❌ wrong password
    VALUES (p_login, v_ip, v_user.user_id, v_user.username, v_user.email, FALSE, 'Invalid password');
    RETURN;
  END IF;
END;
$$;


