-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    user_id integer NOT NULL,
    username character varying(255) NOT NULL,
    email character varying(255) NOT NULL,
    first_name character varying(255),
    last_name character varying(255),
    phone_number character varying(50),
    title character varying(100),
    is_active boolean DEFAULT true,
    assigned_region_id integer,
    assigned_province_id integer,
    assigned_district_id integer,
    assigned_facility_id integer,
    is_national_access boolean DEFAULT false,
    profile text,
    photo character varying(255),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone,
    last_login timestamp without time zone,
    accessible_regions integer[],
    accessible_provinces integer[],
    accessible_districts integer[],
    accessible_facilities integer[],
    escalation_level character varying(20) DEFAULT 'facility'::character varying,
    can_escalate_to text[] DEFAULT '{}'::text[],
    role_id integer,
    password_hash text,
    must_change_password boolean DEFAULT false,
    password text,
    password_reset_required boolean DEFAULT false,
    notification_preferences jsonb DEFAULT '{"sms": false, "email": true, "inApp": true, "whatsapp": false, "sla_breach": true, "ticket_created": true, "ticket_assigned": true, "ticket_resolved": true, "ticket_escalated": true}'::jsonb,
    CONSTRAINT ck_location_scope_v2 CHECK ((((is_national_access = true) AND (COALESCE(assigned_region_id, assigned_province_id, assigned_district_id, assigned_facility_id) IS NULL)) OR (is_national_access = false)))
);


--
-- Name: COLUMN users.is_national_access; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.is_national_access IS 'Flag indicating if user has national-level access';


--
-- Name: COLUMN users.accessible_regions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.accessible_regions IS 'Array of region IDs user can access';


--
-- Name: COLUMN users.accessible_provinces; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.accessible_provinces IS 'Array of province IDs user can access';


--
-- Name: COLUMN users.accessible_districts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.accessible_districts IS 'Array of district IDs user can access';


--
-- Name: COLUMN users.accessible_facilities; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.accessible_facilities IS 'Array of facility IDs user can access';


--
-- Name: COLUMN users.notification_preferences; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.notification_preferences IS 'JSON storing user notification channel preferences';


--
-- Name: users_user_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.users_user_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: users_user_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.users_user_id_seq OWNED BY public.users.user_id;


--
-- Name: v_user_access; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_access AS
 SELECT u.user_id,
    r.role_id,
    r.role_name,
    p.permission_id,
    p.permission_name,
    p.category,
    p.resource,
    p.action,
    p.scope
   FROM ((((public.users u
     LEFT JOIN public.user_roles ur ON ((ur.user_id = u.user_id)))
     LEFT JOIN public.roles r ON ((r.role_id = ur.role_id)))
     LEFT JOIN public.role_permissions rp ON (((rp.role_id = r.role_id) AND (rp.is_allowed = true))))
     LEFT JOIN public.permissions p ON ((p.permission_id = rp.permission_id)))
UNION
 SELECT up.user_id,
    u.role_id,
    r.role_name,
    p.permission_id,
    p.permission_name,
    p.category,
    p.resource,
    p.action,
    p.scope
   FROM (((public.user_permissions up
     LEFT JOIN public.users u ON ((u.user_id = up.user_id)))
     LEFT JOIN public.roles r ON ((r.role_id = u.role_id)))
     LEFT JOIN public.permissions p ON ((p.permission_id = up.permission_id)));


--
-- Name: v_user_access_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_access_summary AS
 SELECT u.user_id,
    u.username,
    u.email,
    r.role_name,
    g.group_name,
    p.permission_name,
    p.category,
    p.resource,
    p.action,
    p.scope
   FROM ((((((public.users u
     LEFT JOIN public.user_roles ur ON ((ur.user_id = u.user_id)))
     LEFT JOIN public.roles r ON ((ur.role_id = r.role_id)))
     LEFT JOIN public.user_group_members gm ON ((gm.user_id = u.user_id)))
     LEFT JOIN public.user_groups g ON ((gm.group_id = g.group_id)))
     LEFT JOIN public.user_permissions up ON ((up.user_id = u.user_id)))
     LEFT JOIN public.permissions p ON ((up.permission_id = p.permission_id)));


--
-- Name: v_user_roles; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_roles AS
 SELECT ur.user_id,
    r.role_id,
    r.role_name
   FROM (public.user_roles ur
     JOIN public.roles r ON ((r.role_id = ur.role_id)));


--
-- Name: v_user_scope; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_scope AS
 SELECT user_id,
    assigned_facility_id AS facility_id,
    assigned_district_id AS district_id,
    assigned_province_id AS province_id,
    assigned_region_id AS region_id
   FROM public.users u;


--
-- Name: vw_user_access; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_user_access AS
 SELECT u.user_id,
    u.username,
    u.email,
    COALESCE(u.first_name, ''::character varying) AS first_name,
    COALESCE(u.last_name, ''::character varying) AS last_name,
    r.role_id,
    r.role_name,
    g.group_id,
    g.group_name,
    p.permission_id,
    p.permission_name,
    p.category,
    p.resource,
    p.action,
    p.scope,
    gp.is_allowed
   FROM (((((public.users u
     JOIN public.user_group_membership ugm ON ((u.user_id = ugm.user_id)))
     JOIN public.user_groups g ON ((ugm.group_id = g.group_id)))
     JOIN public.roles r ON ((g.role_id = r.role_id)))
     JOIN public.group_permissions gp ON ((g.group_id = gp.group_id)))
     JOIN public.permissions p ON ((gp.permission_id = p.permission_id)))
  WHERE (u.is_active = true);


